/// Find the leftmost node of a polygon ring.
pub(super) fn get_leftmost(&self, start: usize) -> usize {
    let mut p = start;
    let mut leftmost = start;
    loop {
        let (np, nl) = (&self.nodes[p], &self.nodes[leftmost]);
        if np.x < nl.x || (np.x == nl.x && np.y < nl.y) {
            leftmost = p;
        }
        p = self.nodes[p].next;
        if p == start {
            return leftmost;
        }
    }
}

