//! Generation of the Archimedean spiral ring fed to the triangulator.

use std::f64::consts::PI;

/// Sample `2 * n` points of a spiral whose radius grows linearly with the
/// parameter `t` over two full turns.
///
/// The arithmetic mirrors the C++ source term by term — `t` is the integer ratio
/// `i / (n * 2)` and the angle is `(4.0 * PI) * t` — so the sampled coordinates
/// are bit-identical doubles.
pub fn spiral(n: i32) -> Vec<[f64; 2]> {
    let count = n.wrapping_mul(2);
    let mut points: Vec<[f64; 2]> = Vec::new();

    let mut i: i32 = 0;
    while i < count {
        let t = f64::from(i) / f64::from(count);
        let radius = t;
        let angle = 4.0 * PI * t;
        points.push([radius * angle.cos(), radius * angle.sin()]);
        i += 1;
    }

    points
}

pub fn run(&mut self, points: &[Vec<[f64; 2]>]) {
    // reset
    self.indices.clear();
    self.vertices = 0;
    self.nodes.clear();
    self.hashing = false;
    self.inv_size = 0.0;

    if points.is_empty() {
        return;
    }

    // The z-order hash only pays off past a vertex count threshold; the loop
    // stops early once the budget is blown, matching the reference exactly.
    let mut threshold: i32 = 80;
    let mut len: usize = 0;
    let mut i = 0;
    while threshold >= 0 && i < points.len() {
        threshold -= points[i].len() as i32;
        len += points[i].len();
        i += 1;
    }

    // estimate size of nodes and indices
    self.nodes.reserve(len * 3 / 2);
    self.indices.reserve(len + points[0].len());

    let mut outer_node = self.linked_list(&points[0], true);
    if outer_node == NIL || self.nodes[outer_node].prev == self.nodes[outer_node].next {
        return;
    }

    if points.len() > 1 {
        outer_node = self.eliminate_holes(points, outer_node);
    }

    // if the shape is not too simple, we'll use z-order curve hash later;
    // calculate polygon bbox
    self.hashing = threshold < 0;
    if self.hashing {
        let mut p = self.nodes[outer_node].next;
        self.min_x = self.nodes[outer_node].x;
        self.max_x = self.min_x;
        self.min_y = self.nodes[outer_node].y;
        self.max_y = self.min_y;
        loop {
            let (x, y) = (self.nodes[p].x, self.nodes[p].y);
            self.min_x = self.min_x.min(x);
            self.min_y = self.min_y.min(y);
            self.max_x = self.max_x.max(x);
            self.max_y = self.max_y.max(y);
            p = self.nodes[p].next;
            if p == outer_node {
                break;
            }
        }

        // min_x, min_y and inv_size are later used to transform coords into
        // integers for z-order calculation
        self.inv_size = (self.max_x - self.min_x).max(self.max_y - self.min_y);
        self.inv_size = if self.inv_size != 0.0 {
            32767.0 / self.inv_size
        } else {
            0.0
        };
    }

    self.earcut_linked(outer_node, 0);
}

